function sortAllSections() {
    document.querySelectorAll('.month-section').forEach(section => {
        sortEvents(section);
    });
}

// 自動排序單一容器內的活動
function sortEvents(container) {
    if (!container) return;

    // 取得除了 header 以外的所有 event-item
    const items = Array.from(container.querySelectorAll('.event-item'));

    items.sort((a, b) => {
        const dateA = parseDateScore(a.querySelector('.event-date').innerText);
        const dateB = parseDateScore(b.querySelector('.event-date').innerText);
        return dateA - dateB;
    });

    // 重新加入到 container (這會移動它們的順序)
    items.forEach(item => container.appendChild(item));
}

// 將日期字串轉換為可比較的數字 (增強版：支援全形、空格、不同分隔符，及範圍如 03/7-8)
function parseDateScore(dateStr) {
    // 1. 全形轉半形
    let normalized = dateStr.replace(/[\uff01-\uff5e]/g, function(ch) {
        return String.fromCharCode(ch.charCodeAt(0) - 0xfee0);
    });

    // 2. 處理範圍，只取第一個日期 (e.g., 03/7-8 -> 03/7)
    normalized = normalized.split('-')[0].trim();

    // 3. 移除可能的干擾字符，只抓取前兩組數字
    // 支援格式： 3/12, 3-12, 3.12, 03/12
    const match = normalized.match(/(\d+)[\/\-\.](\d+)/);

    if (match) {
        // 月 * 100 + 日 (例如 3/12 -> 312, 12/5 -> 1205)
